-- Identity: users and their preferences.
-- Ids are UUIDs generated by the application; the default is a fallback for manual inserts.

CREATE TABLE users (
    id              UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    email           VARCHAR(254) NOT NULL,
    password_hash   VARCHAR(255) NOT NULL,
    full_name       VARCHAR(100) NOT NULL,
    status          VARCHAR(20)  NOT NULL DEFAULT 'ACTIVE',
    last_login_at   TIMESTAMPTZ,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version         BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT uk_users_email UNIQUE (email),
    -- Emails are stored normalised so uniqueness is case-insensitive.
    CONSTRAINT ck_users_email_normalised CHECK (email = lower(btrim(email))),
    CONSTRAINT ck_users_full_name_not_blank CHECK (btrim(full_name) <> ''),
    CONSTRAINT ck_users_status CHECK (status IN ('ACTIVE', 'DISABLED'))
);

CREATE TABLE user_preferences (
    user_id           UUID        PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    default_currency  VARCHAR(3)  NOT NULL DEFAULT 'INR',
    timezone          VARCHAR(64) NOT NULL DEFAULT 'Asia/Kolkata',
    week_start_day    VARCHAR(9)  NOT NULL DEFAULT 'MONDAY',
    theme             VARCHAR(10) NOT NULL DEFAULT 'SYSTEM',
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    version           BIGINT      NOT NULL DEFAULT 0,
    CONSTRAINT ck_user_preferences_currency CHECK (default_currency ~ '^[A-Z]{3}$'),
    CONSTRAINT ck_user_preferences_week_start CHECK (week_start_day IN
        ('MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY', 'SUNDAY')),
    CONSTRAINT ck_user_preferences_theme CHECK (theme IN ('SYSTEM', 'LIGHT', 'DARK'))
);
